theorem ProbabilityTheory.Kernel.extracted_1.{u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U] {κ η : Kernel T (S × U)}
  {μ : Measure T} (h : ⇑κ =ᶠ[ae μ] ⇑η) (h1 : ⇑κ.fst =ᶠ[ae μ] ⇑η.fst) : ⇑κ.snd =ᶠ[ae μ] ⇑η.snd := by
  filter_upwards [h] with t ht
      rw [snd_apply, ht, snd_apply]

