theorem ProbabilityTheory.Kernel.extracted_1.{u_5, u_4, u_3, u_2} {S : Type u_2} {T : Type u_3} {U : Type u_4}
  {V : Type u_5} [inst : MeasurableSpace S] [inst_1 : MeasurableSpace T] [inst_2 : MeasurableSpace U]
  [inst_3 : MeasurableSpace V] [inst_4 : Countable S] [inst_5 : MeasurableSingletonClass S] [inst_6 : Countable T]
  [inst_7 : MeasurableSingletonClass T] [inst_8 : Countable U] [inst_9 : MeasurableSingletonClass U]
  [inst_10 : Countable V] [inst_11 : MeasurableSingletonClass V] {κ : Kernel T (S × U × V)}
  [inst_12 : IsZeroOrMarkovKernel κ] {μ : Measure T} [inst_13 : IsZeroOrProbabilityMeasure μ]
  [inst_14 : FiniteSupport μ] (hκ : κ.AEFiniteKernelSupport μ) (hκ' : IsMarkovKernel κ) (hμ : IsProbabilityMeasure μ)
  (this_1 : Nonempty (S × U × V)) (this_2 : Nonempty U) (this : Nonempty V) :
  let κ' := κ.map ⇑MeasurableEquiv.prodAssoc.symm;
  κ' = κ.map ⇑MeasurableEquiv.prodAssoc.symm →
    let ξ := κ'.fst.fst;
    ξ = κ'.fst.fst →
      let κ'' := κ'.fst.condKernel;
      let η := κ'.condKernel;
      ξ = κ.fst →
        ξ ⊗ₖ κ'' = κ'.fst →
          ξ ⊗ₖ κ'' ⊗ₖ η = κ' →
            ξ ⊗ₖ (κ'' ⊗ₖ η.comap ⇑MeasurableEquiv.prodAssoc ⋯) = κ → ξ.AEFiniteKernelSupport μ := by
  fun_prop

